package coordination

import (
	"fmt"
	"path"
	"strings"
)

type RuleStatus string

const (
	RuleCurrent    RuleStatus = "current"
	RuleSuperseded RuleStatus = "superseded"
)

type CertificationAuthority string

const CertificationMaintainer CertificationAuthority = "maintainer"

type RuleCertification struct {
	CertifiedBy string                 `json:"certifiedBy"`
	Authority   CertificationAuthority `json:"authority"`
}

// ArchitectureRule is an executable policy derived from a descriptive decision
// record. Only current rules certified by a maintainer participate in admission.
type ArchitectureRule struct {
	ID               string            `json:"id"`
	Revision         int               `json:"revision"`
	Status           RuleStatus        `json:"status"`
	Title            string            `json:"title"`
	Rationale        string            `json:"rationale"`
	SourceRecordID   string            `json:"sourceRecordId"`
	ScopePrefixes    []string          `json:"scopePrefixes"`
	ProhibitedTraits []string          `json:"prohibitedTraits,omitempty"`
	RequiredTraits   []string          `json:"requiredTraits,omitempty"`
	Certification    RuleCertification `json:"certification"`
}

type ProposedChange struct {
	Path   string   `json:"path"`
	Traits []string `json:"traits"`
}

type WorkProposal struct {
	Agent     string           `json:"agent"`
	Objective string           `json:"objective"`
	Changes   []ProposedChange `json:"changes"`
}

type FindingKind string

const (
	FindingContradiction   FindingKind = "contradiction"
	FindingUnproven        FindingKind = "unproven"
	FindingInvalidProposal FindingKind = "invalid_proposal"
	FindingInvalidRule     FindingKind = "invalid_rule"
)

type Finding struct {
	Kind         FindingKind `json:"kind"`
	RuleID       string      `json:"ruleId,omitempty"`
	RuleRevision int         `json:"ruleRevision,omitempty"`
	ChangePath   string      `json:"changePath,omitempty"`
	Trait        string      `json:"trait,omitempty"`
	Message      string      `json:"message"`
}

type AdmissionStatus string

const (
	AdmissionAllowed AdmissionStatus = "allowed"
	AdmissionBlocked AdmissionStatus = "blocked"
)

type Evaluation struct {
	Status   AdmissionStatus `json:"status"`
	Findings []Finding       `json:"findings,omitempty"`
}

func (e Evaluation) Allowed() bool {
	return e.Status == AdmissionAllowed
}

// AdmissionError is returned by Admit when work must not proceed.
type AdmissionError struct {
	Findings []Finding
}

func (e *AdmissionError) Error() string {
	if len(e.Findings) == 0 {
		return "architecture policy blocked the proposal"
	}
	if len(e.Findings) == 1 {
		return "architecture policy blocked the proposal: " + e.Findings[0].Message
	}
	return fmt.Sprintf("architecture policy blocked the proposal: %s (and %d more findings)", e.Findings[0].Message, len(e.Findings)-1)
}

type ArchitecturePolicy struct {
	Rules []ArchitectureRule
}

// Admit evaluates the proposal and returns an error that callers must treat as
// a hard stop. Evaluation is returned in both allowed and blocked cases so the
// caller can present structured reasons to the agent.
func (p ArchitecturePolicy) Admit(proposal WorkProposal) (Evaluation, error) {
	evaluation := p.Evaluate(proposal)
	if evaluation.Allowed() {
		return evaluation, nil
	}
	return evaluation, &AdmissionError{Findings: append([]Finding(nil), evaluation.Findings...)}
}

// Evaluate applies current certified rules to a structured proposal. It fails
// closed: malformed proposals, invalid active rules, contradictions, and absent
// evidence required by an applicable rule all produce a blocked evaluation.
func (p ArchitecturePolicy) Evaluate(proposal WorkProposal) Evaluation {
	findings := validateProposal(proposal)

	for _, rule := range p.Rules {
		if rule.Status == RuleSuperseded {
			continue
		}

		ruleFindings := validateCurrentRule(rule)
		if len(ruleFindings) > 0 {
			findings = append(findings, ruleFindings...)
			continue
		}

		prohibited := traitSet(rule.ProhibitedTraits)
		required := traitSet(rule.RequiredTraits)
		for _, change := range proposal.Changes {
			changePath, ok := cleanRepositoryPath(change.Path)
			if !ok || !ruleApplies(rule.ScopePrefixes, changePath) {
				continue
			}

			traits := traitSet(change.Traits)
			for trait := range prohibited {
				if _, present := traits[trait]; present {
					findings = append(findings, Finding{
						Kind:         FindingContradiction,
						RuleID:       rule.ID,
						RuleRevision: rule.Revision,
						ChangePath:   changePath,
						Trait:        trait,
						Message:      fmt.Sprintf("%s prohibits trait %q in %s", rule.ID, trait, changePath),
					})
				}
			}
			for trait := range required {
				if _, present := traits[trait]; !present {
					findings = append(findings, Finding{
						Kind:         FindingUnproven,
						RuleID:       rule.ID,
						RuleRevision: rule.Revision,
						ChangePath:   changePath,
						Trait:        trait,
						Message:      fmt.Sprintf("%s requires trait %q for %s, but the proposal does not declare it", rule.ID, trait, changePath),
					})
				}
			}
		}
	}

	status := AdmissionAllowed
	if len(findings) > 0 {
		status = AdmissionBlocked
	}
	return Evaluation{Status: status, Findings: findings}
}

func validateProposal(proposal WorkProposal) []Finding {
	var findings []Finding
	if strings.TrimSpace(proposal.Agent) == "" {
		findings = append(findings, invalidProposal("proposal must identify the agent"))
	}
	if strings.TrimSpace(proposal.Objective) == "" {
		findings = append(findings, invalidProposal("proposal must state an objective"))
	}
	if len(proposal.Changes) == 0 {
		findings = append(findings, invalidProposal("proposal must declare at least one change"))
	}
	for _, change := range proposal.Changes {
		changePath, ok := cleanRepositoryPath(change.Path)
		if !ok {
			findings = append(findings, invalidProposal(fmt.Sprintf("proposal contains invalid repository path %q", change.Path)))
			continue
		}
		for _, trait := range change.Traits {
			if canonicalTrait(trait) == "" {
				findings = append(findings, Finding{
					Kind:       FindingInvalidProposal,
					ChangePath: changePath,
					Message:    fmt.Sprintf("proposal contains an empty trait for %s", changePath),
				})
			}
		}
	}
	return findings
}

func validateCurrentRule(rule ArchitectureRule) []Finding {
	var messages []string
	if strings.TrimSpace(rule.ID) == "" {
		messages = append(messages, "rule ID is required")
	}
	if rule.Revision < 1 {
		messages = append(messages, "rule revision must be positive")
	}
	if rule.Status != RuleCurrent {
		messages = append(messages, fmt.Sprintf("rule status %q is not supported", rule.Status))
	}
	if strings.TrimSpace(rule.Title) == "" {
		messages = append(messages, "rule title is required")
	}
	if strings.TrimSpace(rule.Rationale) == "" {
		messages = append(messages, "rule rationale is required")
	}
	if strings.TrimSpace(rule.SourceRecordID) == "" {
		messages = append(messages, "source decision record ID is required")
	}
	if strings.TrimSpace(rule.Certification.CertifiedBy) == "" {
		messages = append(messages, "certifying principal is required")
	}
	if rule.Certification.Authority != CertificationMaintainer {
		messages = append(messages, "current rule must be certified by maintainer authority")
	}
	if len(rule.ScopePrefixes) == 0 {
		messages = append(messages, "at least one scope prefix is required")
	}
	for _, prefix := range rule.ScopePrefixes {
		if _, ok := cleanScopePrefix(prefix); !ok {
			messages = append(messages, fmt.Sprintf("scope prefix %q is invalid", prefix))
		}
	}
	if len(rule.ProhibitedTraits) == 0 && len(rule.RequiredTraits) == 0 {
		messages = append(messages, "at least one prohibited or required trait is required")
	}

	prohibited := traitSet(rule.ProhibitedTraits)
	required := traitSet(rule.RequiredTraits)
	for _, trait := range append(append([]string(nil), rule.ProhibitedTraits...), rule.RequiredTraits...) {
		if canonicalTrait(trait) == "" {
			messages = append(messages, "rule traits must not be empty")
		}
	}
	for trait := range prohibited {
		if _, conflict := required[trait]; conflict {
			messages = append(messages, fmt.Sprintf("trait %q cannot be both prohibited and required", trait))
		}
	}

	findings := make([]Finding, 0, len(messages))
	for _, message := range messages {
		findings = append(findings, Finding{
			Kind:         FindingInvalidRule,
			RuleID:       rule.ID,
			RuleRevision: rule.Revision,
			Message:      message,
		})
	}
	return findings
}

func invalidProposal(message string) Finding {
	return Finding{Kind: FindingInvalidProposal, Message: message}
}

func traitSet(traits []string) map[string]struct{} {
	set := make(map[string]struct{}, len(traits))
	for _, trait := range traits {
		if trait = canonicalTrait(trait); trait != "" {
			set[trait] = struct{}{}
		}
	}
	return set
}

func canonicalTrait(trait string) string {
	return strings.ToLower(strings.TrimSpace(trait))
}

func ruleApplies(prefixes []string, changePath string) bool {
	for _, prefix := range prefixes {
		prefix, ok := cleanScopePrefix(prefix)
		if !ok {
			continue
		}
		if prefix == "." || changePath == prefix || strings.HasPrefix(changePath, prefix+"/") {
			return true
		}
	}
	return false
}

func cleanRepositoryPath(value string) (string, bool) {
	value = strings.TrimSpace(value)
	if value == "" || strings.HasPrefix(value, "/") {
		return "", false
	}
	cleaned := path.Clean(value)
	if cleaned == "." || cleaned == ".." || strings.HasPrefix(cleaned, "../") {
		return "", false
	}
	return cleaned, true
}

func cleanScopePrefix(value string) (string, bool) {
	value = strings.TrimSpace(value)
	if value == "." {
		return value, true
	}
	return cleanRepositoryPath(value)
}
package coordination

import (
	"errors"
	"testing"
)

func TestArchitecturePolicyBlocksContradictingProposal(t *testing.T) {
	policy := ArchitecturePolicy{Rules: []ArchitectureRule{providerNeutralRule()}}
	proposal := validProposal(ProposedChange{
		Path:   "internal/coordination/provider.go",
		Traits: []string{"provider-specific-dependency"},
	})

	evaluation, err := policy.Admit(proposal)
	if err == nil {
		t.Fatal("expected proposal to be blocked")
	}
	var admissionErr *AdmissionError
	if !errors.As(err, &admissionErr) {
		t.Fatalf("expected AdmissionError, got %T", err)
	}
	if evaluation.Status != AdmissionBlocked || len(evaluation.Findings) != 1 {
		t.Fatalf("unexpected evaluation: %#v", evaluation)
	}
	finding := evaluation.Findings[0]
	if finding.Kind != FindingContradiction || finding.RuleID != "core-provider-neutral" {
		t.Fatalf("unexpected finding: %#v", finding)
	}
}

func TestArchitecturePolicyAllowsOutOfScopeProposal(t *testing.T) {
	policy := ArchitecturePolicy{Rules: []ArchitectureRule{providerNeutralRule()}}
	proposal := validProposal(ProposedChange{
		Path:   "internal/providers/anthropic/client.go",
		Traits: []string{"provider-specific-dependency"},
	})

	evaluation, err := policy.Admit(proposal)
	if err != nil {
		t.Fatalf("expected proposal to be allowed: %v", err)
	}
	if !evaluation.Allowed() {
		t.Fatalf("unexpected evaluation: %#v", evaluation)
	}
}

func TestArchitecturePolicyRequiresDeclaredEvidence(t *testing.T) {
	rule := providerNeutralRule()
	rule.ProhibitedTraits = nil
	rule.RequiredTraits = []string{"provider-neutral"}
	policy := ArchitecturePolicy{Rules: []ArchitectureRule{rule}}

	evaluation, err := policy.Admit(validProposal(ProposedChange{Path: "internal/coordination/brief.go"}))
	if err == nil {
		t.Fatal("expected proposal without required evidence to be blocked")
	}
	if len(evaluation.Findings) != 1 || evaluation.Findings[0].Kind != FindingUnproven {
		t.Fatalf("unexpected evaluation: %#v", evaluation)
	}
}

func TestArchitecturePolicyFailsClosedForUncertifiedCurrentRule(t *testing.T) {
	rule := providerNeutralRule()
	rule.Certification = RuleCertification{}
	policy := ArchitecturePolicy{Rules: []ArchitectureRule{rule}}

	evaluation, err := policy.Admit(validProposal(ProposedChange{Path: "README.md"}))
	if err == nil {
		t.Fatal("expected invalid active policy to block admission")
	}
	if len(evaluation.Findings) == 0 || evaluation.Findings[0].Kind != FindingInvalidRule {
		t.Fatalf("unexpected evaluation: %#v", evaluation)
	}
}

func TestArchitecturePolicyIgnoresSupersededRule(t *testing.T) {
	rule := providerNeutralRule()
	rule.Status = RuleSuperseded
	policy := ArchitecturePolicy{Rules: []ArchitectureRule{rule}}
	proposal := validProposal(ProposedChange{
		Path:   "internal/coordination/provider.go",
		Traits: []string{"provider-specific-dependency"},
	})

	evaluation, err := policy.Admit(proposal)
	if err != nil || !evaluation.Allowed() {
		t.Fatalf("expected superseded rule not to apply: evaluation=%#v err=%v", evaluation, err)
	}
}

func TestArchitecturePolicyScopeUsesPathBoundaries(t *testing.T) {
	policy := ArchitecturePolicy{Rules: []ArchitectureRule{providerNeutralRule()}}
	proposal := validProposal(ProposedChange{
		Path:   "internal/coordination-old/provider.go",
		Traits: []string{"provider-specific-dependency"},
	})

	evaluation, err := policy.Admit(proposal)
	if err != nil || !evaluation.Allowed() {
		t.Fatalf("expected similarly named directory to remain out of scope: evaluation=%#v err=%v", evaluation, err)
	}
}

func providerNeutralRule() ArchitectureRule {
	return ArchitectureRule{
		ID:               "core-provider-neutral",
		Revision:         1,
		Status:           RuleCurrent,
		Title:            "Keep coordination provider-neutral",
		Rationale:        "Coordination behavior must be consistent across coding harnesses and providers.",
		SourceRecordID:   "decision-provider-neutral",
