	if strings.TrimSpace(proposal.Objective) == "" {
		findings = append(findings, invalidProposal("proposal must state an objective"))
	}
	if len(proposal.Changes) == 0 {
		findings = append(findings, invalidProposal("proposal must declare at least one change"))
	}
	for _, change := range proposal.Changes {
		changePath, ok := cleanRepositoryPath(change.Path)
		if !ok {
			findings = append(findings, invalidProposal(fmt.Sprintf("proposal contains invalid repository path %q", change.Path)))
			continue
		}
		for _, trait := range change.Traits {
			if canonicalTrait(trait) == "" {
				findings = append(findings, Finding{
					Kind:       FindingInvalidProposal,
					ChangePath: changePath,
					Message:    fmt.Sprintf("proposal contains an empty trait for %s", changePath),
				})
			}
		}
	}
	return findings
}

func validateCurrentRule(rule ArchitectureRule) []Finding {
	var messages []string
	if strings.TrimSpace(rule.ID) == "" {
		messages = append(messages, "rule ID is required")
	}
	if rule.Revision < 1 {
		messages = append(messages, "rule revision must be positive")
	}
	if rule.Status != RuleCurrent {
		messages = append(messages, fmt.Sprintf("rule status %q is not supported", rule.Status))
	}
	if strings.TrimSpace(rule.Title) == "" {
		messages = append(messages, "rule title is required")
