	return findings
}

func validateCurrentRule(rule ArchitectureRule) []Finding {
	var messages []string
	if strings.TrimSpace(rule.ID) == "" {
		messages = append(messages, "rule ID is required")
	}
	if rule.Revision < 1 {
		messages = append(messages, "rule revision must be positive")
	}
	if rule.Status != RuleCurrent {
		messages = append(messages, fmt.Sprintf("rule status %q is not supported", rule.Status))
	}
	if strings.TrimSpace(rule.Title) == "" {
		messages = append(messages, "rule title is required")
	}
	if strings.TrimSpace(rule.Rationale) == "" {
		messages = append(messages, "rule rationale is required")
	}
	if strings.TrimSpace(rule.SourceRecordID) == "" {
		messages = append(messages, "source decision record ID is required")
	}
	if strings.TrimSpace(rule.Certification.CertifiedBy) == "" {
		messages = append(messages, "certifying principal is required")
	}
	if rule.Certification.Authority != CertificationMaintainer {
		messages = append(messages, "current rule must be certified by maintainer authority")
	}
	if len(rule.ScopePrefixes) == 0 {
		messages = append(messages, "at least one scope prefix is required")
	}
	for _, prefix := range rule.ScopePrefixes {
		if _, ok := cleanScopePrefix(prefix); !ok {
			messages = append(messages, fmt.Sprintf("scope prefix %q is invalid", prefix))
		}
	}
	if len(rule.Constraints) == 0 {
		messages = append(messages, "at least one constraint is required")
	}
	seenProperties := make(map[string]struct{}, len(rule.Constraints))
	for _, constraint := range rule.Constraints {
		property := canonicalProperty(constraint.Property)
		if property == "" {
			messages = append(messages, "constraint property must not be empty")
			continue
		}
		if _, duplicate := seenProperties[property]; duplicate {
			messages = append(messages, fmt.Sprintf("constraint property %q is declared more than once", property))
		}
		seenProperties[property] = struct{}{}
		if len(constraint.AllowedValues) == 0 {
			messages = append(messages, fmt.Sprintf("constraint %q must allow at least one value", property))
		}
		for _, value := range constraint.AllowedValues {
			if canonicalValue(value) == "" {
				messages = append(messages, fmt.Sprintf("constraint %q contains an empty allowed value", property))
			}
		}
	}

	findings := make([]Finding, 0, len(messages))
	for _, message := range messages {
		findings = append(findings, Finding{
			Kind:         FindingInvalidRule,
			RuleID:       rule.ID,
			RuleRevision: rule.Revision,
			Message:      message,
		})
	}
	return findings
}

func invalidProposal(message string) Finding {
	return Finding{Kind: FindingInvalidProposal, Message: message}
}

func claimMap(claims map[string]string) map[string]string {
	canonical := make(map[string]string, len(claims))
	for property, value := range claims {
		if property = canonicalProperty(property); property != "" {
			canonical[property] = canonicalValue(value)
		}
	}
	return canonical
}

func valueSet(values []string) map[string]struct{} {
	set := make(map[string]struct{}, len(values))
	for _, value := range values {
		if value = canonicalValue(value); value != "" {
			set[value] = struct{}{}
		}
	}
	return set
}

func canonicalProperty(property string) string {
	return strings.ToLower(strings.TrimSpace(property))
}

func canonicalValue(value string) string {
	return strings.ToLower(strings.TrimSpace(value))
}

func ruleApplies(prefixes []string, changePath string) bool {
	for _, prefix := range prefixes {
		prefix, ok := cleanScopePrefix(prefix)
		if !ok {
			continue
		}
		if prefix == "." || changePath == prefix || strings.HasPrefix(changePath, prefix+"/") {
			return true
		}
	}
	return false
}

func cleanRepositoryPath(value string) (string, bool) {
	value = strings.TrimSpace(value)
	if value == "" || strings.HasPrefix(value, "/") || strings.Contains(value, "\\") {
		return "", false
	}
	cleaned := path.Clean(value)
	if cleaned == "." || cleaned == ".." || strings.HasPrefix(cleaned, "../") {
		return "", false
	}
	return cleaned, true
}

func cleanScopePrefix(value string) (string, bool) {
	value = strings.TrimSpace(value)
	if value == "." {
		return value, true
	}
	return cleanRepositoryPath(value)
}

