    15	func run(output io.Writer) int {
    16		policy := coordination.ArchitecturePolicy{Rules: []coordination.ArchitectureRule{
    17			{
    18				ID:             "core-provider-neutral",
    19				Revision:       1,
    20				Status:         coordination.RuleCurrent,
    21				Title:          "Keep coordination provider-neutral",
    22				Rationale:      "The coordination core must behave consistently across agent providers.",
    23				SourceRecordID: "decision-provider-neutral",
    24				ScopePrefixes:  []string{"internal/coordination"},
    25				Constraints: []coordination.RuleConstraint{
    26					{Property: "provider-coupling", AllowedValues: []string{"neutral"}},
    27				},
    28				Certification: coordination.RuleCertification{
    29					CertifiedBy: "relaydesk-maintainer",
    30					Authority:   coordination.CertificationMaintainer,
    31				},
    32			},
    33		}}
    34		proposal := coordination.WorkProposal{
    35			Agent:     "example-agent",
    36			Objective: "Add a provider client directly to the coordination core",
    37			Changes: []coordination.ProposedChange{
    38				{
    39					Path:   "internal/coordination/provider.go",
    40					Claims: map[string]string{"provider-coupling": "provider-specific"},
    41				},
    42			},
    43		}
    44	
    45		evaluation, admissionErr := policy.Admit(proposal)
    46		result := struct {
    47			Proposal   coordination.WorkProposal `json:"proposal"`
    48			Evaluation coordination.Evaluation   `json:"evaluation"`
    49		}{Proposal: proposal, Evaluation: evaluation}
    50		if err := json.NewEncoder(output).Encode(result); err != nil {
    51			return 2
    52		}
    53		if admissionErr != nil {
    54			return 1
    55		}
    56		return 0
    57	}
